import {LOCAL_SPECIALTY_IDS,CURRENT_PATHS,STMG_SPECIFICS,VERIFIED_SOURCES,HEALTH_UPDATE,levelContent,selectionIssue} from './student-content.mjs';
import {exportPDF} from './pdf.mjs';
import {UPDATED,URLS,LEVELS,SPECIALTIES,DOMAINS,FAMILY_LABELS,RESOURCES,GUIDES,PATHWAYS,TECH_SERIES,LOCAL_OFFERS,REORIENTATION_STEPS,DOMAIN_RULES} from './content.mjs';
import {normalize,escapeHTML as e,safeURL,combinations,toggleSelection,formatNumber as num,formatPct as pct,filterFormations,newProject,validateProject,budgetSummary,progressSections,projectHTML,formationHTML,guideHTML,analyzeScenario} from './core.mjs';

const $=(s,root=document)=>root.querySelector(s);
const paths={home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z"/>',map:'<path d="m3 5 6-2 6 2 6-2v16l-6 2-6-2-6 2zM9 3v16M15 5v16"/>',branch:'<circle cx="6" cy="5" r="2"/><circle cx="18" cy="5" r="2"/><circle cx="12" cy="19" r="2"/><path d="M6 7v2a6 6 0 0 0 6 6v2M18 7v2a6 6 0 0 1-6 6"/>',search:'<circle cx="10" cy="10" r="6.5"/><path d="m15 15 6 6"/>',compass:'<circle cx="12" cy="12" r="9"/><path d="m16 8-2 6-6 2 2-6z"/>',book:'<path d="M12 5v16M3 3c4-1 6 0 9 2 3-2 5-3 9-2v16c-4-1-6 0-9 2-3-2-5-3-9-2z"/>',edit:'<path d="M12 5H5a2 2 0 0 0-2 2v12a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2v-7M16 3l5 5M10 9l7-7 5 5-7 7-7 2z"/>',help:'<circle cx="12" cy="12" r="9"/><path d="M9 9a3 3 0 0 1 6 0c0 2-3 2-3 5M12 17h.01"/>',heart:'<path d="M20 5a5 5 0 0 0-8 1 5 5 0 0 0-8-1c-5 5 3 11 8 15 5-4 13-10 8-15z"/>',science:'<path d="M9 3h6M10 3v7L4 19a1 1 0 0 0 1 2h14a1 1 0 0 0 1-2l-6-9V3M7 15h10"/>',code:'<path d="m8 6-6 6 6 6m8-12 6 6-6 6M14 3l-4 18"/>',leaf:'<path d="M21 3C8 2 2 6 4 15c5 9 18 4 17-12ZM3 22 16 9"/>',briefcase:'<rect x="3" y="7" width="18" height="14" rx="2"/><path d="M8 7V3h8v4M3 12c6 4 12 4 18 0M10 14h4"/>',balance:'<path d="M12 3v18M7 21h10M3 7h18M6 7l-4 8h8zM18 7l-4 8h8z"/>',people:'<circle cx="9" cy="7" r="4"/><path d="M2 21v-3a7 7 0 0 1 14 0v3M17 4a4 4 0 0 1 0 7M19 14a6 6 0 0 1 3 7"/>',palette:'<path d="M12 3a9 9 0 1 0 0 18h1a2 2 0 0 0 0-4 2 2 0 0 1 0-4h4a4 4 0 0 0 4-4c0-4-5-6-9-6Z"/><path d="M7 8h.01M11 6h.01M16 7h.01M5 12h.01"/>',activity:'<path d="M2 12h5l3-8 4 16 3-8h5"/>',shield:'<path d="m12 2 8 4v6c0 5-8 10-8 10S4 17 4 12V6zM8 12l3 3 5-6"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>'};
const icon=(name)=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]??paths.compass}</svg>`;
const external=(url,label,cls='')=>safeURL(url)?`<a href="${e(safeURL(url))}" target="_blank" rel="noopener noreferrer"${cls?` class="${cls}"`:''}>${e(label)} <span aria-hidden="true">↗</span><span class="sr-only"> (nouvel onglet)</span></a>`:'';
const btn=(action,label,cls='',attrs='')=>`<button type="button" class="btn ${cls}" data-action="${action}" ${attrs}>${label}</button>`;
const callout=(title,text,warning=false)=>`<div class="callout ${warning?'warning':''}">${icon(warning?'help':'people')}<div><strong>${title}</strong><p>${text}</p></div></div>`;
const head=(eyebrow,title,text)=>`<header class="pagehead"><p class="eyebrow">${eyebrow}</p><h1>${title}</h1><p>${text}</p></header>`;
const section=(title,link,label)=>`<div class="section-heading"><h2>${title}</h2>${link?`<a href="#${link}">${label??'Tout explorer'} →</a>`:''}</div>`;
const foot=()=>`<footer class="footer-note"><img src="./assets/logo-rond.jpg" width="48" height="47" alt=""><div><p><strong>Site propriété du Lycée Ambroise Paré · Laval</strong><br>Mon parcours · un outil pour préparer tes choix et en parler.</p><p>Contenus vérifiés le ${UPDATED}. Catalogue historique Parcoursup 2025, hors apprentissage.<br><a href="#aide">Aide, sources et confidentialité</a> · ${external(URLS.lycee,'Le site du lycée')}</p></div></footer>`;
const STORAGE_KEY='ambroise-pare:orientation:temporary-draft:v1';
let project=newProject(), draftEnabled=false, dirty=false, saveError='', saveTimer, toastTimer;
let specialtyScope='local',comparePath=null;
let route='accueil', dataset=null, dataPromise=null, page=1, compare=[], specMode='trio', showScenarioCompare=false, exportBusy=false;
let formationFilters={q:'',academy:'Nantes',family:'',status:'',savedOnly:false};
let resourceFilters={q:'',category:'',level:'',savedOnly:false};
function cleanProject(p){const x=validateProject(p);x.trio=x.trio.filter(id=>SPECIALTIES.some(s=>s.id===id));x.pair=x.pair.filter(id=>SPECIALTIES.some(s=>s.id===id));if(x.trio.length===3)x.pair=x.pair.filter(id=>x.trio.includes(id));for(const level of ['premiere','terminale'])for(let i=0;i<5;i++)if(x.checks[level+'-'+i]!==undefined&&x.checks[level+'-generale-'+i]===undefined)x.checks[level+'-generale-'+i]=x.checks[level+'-'+i];x.resources=x.resources.filter(id=>RESOURCES.some(r=>r.id===id));x.domainIds=x.domainIds.filter(id=>DOMAINS.some(d=>d.id===id));x.pathways=x.pathways.filter(id=>PATHWAYS.some(v=>v.id===id));x.options=x.options.filter(id=>LOCAL_OFFERS.some(v=>v.id===id));if(x.techSeries&&!TECH_SERIES.some(v=>v.id===x.techSeries))x.techSeries='';return x;}
try{const stored=localStorage.getItem(STORAGE_KEY);if(stored){const data=JSON.parse(stored);if(data.consent===true){project=cleanProject(data.project);draftEnabled=true;}}}catch{saveError='Le brouillon local n’a pas pu être relu. Importe ton dernier fichier projet ; le contenu existant n’a pas été effacé.';}
const NAV=[['accueil','home','Accueil'],['niveau','map','Mon niveau'],['voies','branch','Les voies possibles'],['domaines','compass','Mes domaines'],['specialites','branch','Comparer mes choix'],['formations','search','Formations'],['ressources','book','Ressources'],['projet','edit','Mon carnet'],['aide','help','Aide']];
const view=$('#view'),dialog=$('#detail-dialog');
function toast(message){const node=$('#toast');node.textContent=message;node.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>node.classList.remove('visible'),4000);}
function saveDraft(){clearTimeout(saveTimer);if(draftEnabled){try{localStorage.setItem(STORAGE_KEY,JSON.stringify({consent:true,project}));saveError='';}catch{saveError='Le brouillon n’a pas pu être enregistré sur cet appareil. Ton texte reste ouvert : télécharge le fichier projet maintenant.';}}updateProjectIndicators();}
function changed(){project.updatedAt=new Date().toISOString();dirty=true;clearTimeout(saveTimer);saveTimer=setTimeout(saveDraft,500);updateProjectIndicators();}
function updateProjectIndicators(){
  const state=$('#save-state');if(state){state.textContent=saveError|| (draftEnabled?'Brouillon de secours sur cet appareil. Télécharge ton fichier pour le conserver.':'Travail en cours dans cette page. Télécharge ton fichier avant de fermer.');state.classList.toggle('error',Boolean(saveError));}
  const count=$('#project-progress');if(count){const n=progressSections(project);count.textContent=`${n} / 6 rubriques commencées`;$('#progress-bar').style.width=n/6*100+'%';}
  const budget=$('#budget-output');if(budget)budget.innerHTML=budgetOutput();
  document.querySelectorAll('[data-count-for]').forEach(n=>{const f=$(`[data-field="${n.dataset.countFor}"]`);if(f)n.textContent=`${f.value.length.toLocaleString('fr-FR')} caractères — limite à vérifier sur la fiche de la formation.`;});
}
function renderNav(){
  const navHTML=NAV.map(([key,ic,label])=>`<a class="nav-link ${route===key?'active':''}" href="#${key}" ${route===key?'aria-current="page"':''}>${icon(ic)}<span>${label}</span></a>`).join('');
  $('#navigation').innerHTML=navHTML;$('#mobile-navigation').innerHTML=navHTML;$('#mobile-current').textContent=NAV.find(n=>n[0]===route)?.[2]||'Accueil';
  document.title=(NAV.find(n=>n[0]===route)?.[2]??'Accueil')+' · Mon parcours · Ambroise Paré';
}
function checkKey(i){return project.level==='seconde'?'seconde-'+i:project.level+'-'+project.currentPath+'-'+i;}
function comparatorKind(){return comparePath||(project.level==='seconde'?'generale':project.currentPath);}
function comparePicker(){const kind=comparatorKind();return `<div class="level-picker" role="group" aria-label="Parcours à comparer"><button type="button" data-action="compare-path" data-id="generale" class="${kind==='generale'?'selected':''}" aria-pressed="${kind==='generale'}">Voie générale</button><button type="button" data-action="compare-path" data-id="stmg" class="${kind==='stmg'?'selected':''}" aria-pressed="${kind==='stmg'}">STMG</button></div>`;}
function levelPicker(){return `<div class="level-picker" role="group" aria-label="Mon niveau">${Object.entries(LEVELS).map(([id,l])=>`<button type="button" data-action="level" data-id="${id}" class="${project.level===id?'selected':''}" aria-pressed="${project.level===id}">${l.label}</button>`).join('')}</div>`;}
function resourceCard(r){return `<article class="card resource"><div class="tags"><span class="pill">${e(r.category)}</span><span class="pill green">${e(r.type)}</span></div><p class="eyebrow">${e(r.provider)}</p><h3>${e(r.title)}</h3><p>${e(r.description)}</p><div class="actions">${external(r.url,'Consulter','btn')}${btn('resource-save',project.resources.includes(r.id)?'✓ Repérée':'+ Repérer','ghost compact',`data-id="${r.id}" aria-pressed="${project.resources.includes(r.id)}" aria-label="${project.resources.includes(r.id)?'Retirer':'Repérer'} : ${e(r.title)}"`)}</div></article>`;}
function resourceSubset(ids){return `<div class="grid two">${ids.map(id=>RESOURCES.find(r=>r.id===id)).filter(Boolean).map(resourceCard).join('')}</div>`;}
function currentPathPicker(){return project.level==='seconde'?'':`<label class="field track-picker">Mon parcours actuel<select data-current-path>${Object.entries(CURRENT_PATHS).map(([id,label])=>`<option value="${id}" ${project.currentPath===id?'selected':''}>${label}</option>`).join('')}</select><span class="field-note">Les étapes s’adaptent à ta voie. Tes notes sont conservées.</span></label>`;}
function localSnapshot(){return `<details class="card local-snapshot"><summary>Au lycée Ambroise Paré, qu’est-ce qui est proposé ?</summary><div class="grid two" style="margin-top:18px"><div><h3>La voie générale</h3><p class="small">Mathématiques, physique-chimie, SVT, SES, HGGSP, HLP, musique, LLCER anglais, LLCER espagnol, anglais monde contemporain.</p><h3>La STMG</h3><p class="small">En terminale : gestion et finance, mercatique, ressources humaines et communication.</p></div><div><h3>Des parcours et des options</h3><p class="small">En seconde : musique, chinois, italien, latin, grec, management et gestion. Le lycée propose aussi le Bachibac espagnol, des sections européennes anglais et espagnol, le BIA et des dispositifs sportifs. Vérifie les niveaux concernés, les conditions et les possibilités de cumul auprès du lycée.</p><h3>Trois BTS au lycée</h3><p class="small">Comptabilité et gestion · Gestion des transports et logistique associée · Négociation et digitalisation de la relation client.</p></div></div><p class="notice">L’offre ne garantit pas toutes les combinaisons d’emploi du temps. Un seul enseignement de spécialité LLCER peut être choisi. Le Bachibac espagnol n’est pas cumulable avec la spécialité LLCER espagnol. Confirme les choix et modalités pour ta rentrée avec l’équipe.</p><div class="actions">${external(VERIFIED_SOURCES[0][1],'Vérifier l’offre sur Onisep','btn compact')}${external(URLS.lycee,'Consulter le lycée','btn compact')}</div></details>`;}
function renderHome(){const l=levelContent(project),completed=Array.from({length:5},(_,i)=>project.checks[checkKey(i)]).filter(Boolean).length;
 view.innerHTML=`<div class="intro-panel"><div class="intro-copy"><p class="eyebrow">Lycée Ambroise Paré · Ton espace orientation</p><h1>Ton parcours.<br>Un choix à la fois.</h1><p>Tu peux avoir une idée précise, hésiter entre plusieurs envies ou ne pas encore savoir. Ici, découvre tes possibilités et prépare les questions qui t’aideront à avancer.</p>${levelPicker()}<div class="actions"><a class="btn accent" href="#niveau">Commencer en ${l.label.toLowerCase()} →</a><a class="btn ghost" href="#projet">Reprendre mon carnet</a></div></div><aside class="intro-aside"><img src="./assets/logo-complet.jpg" width="916" height="593" alt="Le lycée Ambroise Paré à Laval et son pélican"><div><p class="eyebrow">Tu gardes la main</p><h2>Pas besoin d’avoir déjà toutes les réponses.</h2><p>Compare, note ce qui te plaît, garde plusieurs pistes. Ton projet peut changer.</p><div class="actions">${btn('import','J’ai déjà un fichier projet','compact')}</div></div></aside></div>
 ${section('De quoi as-tu besoin aujourd’hui ?')}<div class="grid three"><a href="#niveau" class="card card-link level-route"><p class="eyebrow">01 · Me repérer</p><h3>Les étapes de mon année</h3><p class="muted small">Des démarches adaptées à la seconde, à la première ou à la terminale et à ta voie.</p><span class="arrow">→</span></a><a href="#specialites" class="card card-link"><p class="eyebrow">02 · Comparer</p><h3>Mes enseignements, mes choix</h3><p class="muted small">Spécialités générales ou enseignements spécifiques de STMG : comprendre ce qui change.</p><span class="arrow">→</span></a><a href="#formations" class="card card-link"><p class="eyebrow">03 · Découvrir</p><h3>Des études après le bac</h3><p class="muted small">Explorer les diplômes, les établissements et les questions à vérifier avant de candidater.</p><span class="arrow">→</span></a></div>
 <div class="next-action"><div><p class="eyebrow">${l.label} · ${l.short}</p><h2>${l.title}</h2><p>${completed} / 5 démarches repérées. Ce n’est ni une note ni une course.</p></div><a class="btn primary" href="#niveau">Voir mes étapes →</a></div>
 ${section('Tu peux aussi partir…')}<div class="grid two"><a href="#domaines" class="card card-link"><span class="card-icon">${icon('compass')}</span><h3>… d’un domaine qui t’attire</h3><p class="small muted">Santé, sciences, droit, création, sport ou plusieurs envies à la fois.</p><span class="arrow">→</span></a><a href="#voies" class="card card-link"><span class="card-icon">${icon('branch')}</span><h3>… d’une façon d’apprendre</h3><p class="small muted">Comprendre les voies générale, technologique et professionnelle, les passerelles et l’apprentissage.</p><span class="arrow">→</span></a></div>${localSnapshot()}
 ${callout('Une question suffit pour commencer.','Ton professeur principal, le Psy-EN et les équipes du lycée peuvent t’aider à faire le point. Tu peux venir avec un carnet encore vide.')}${foot()}`;
}

function stmgContext(){return `<div class="track-context"><p class="eyebrow">STMG · au lycée Ambroise Paré</p><p>En première : sciences de gestion et numérique, management, droit et économie. En terminale : droit et économie et management, sciences de gestion et numérique. Cette dernière spécialité comprend un enseignement spécifique.</p><label class="field">Mon enseignement spécifique envisagé ou suivi<select data-stmg-specific><option value="">Je compare encore</option>${STMG_SPECIFICS.map(v=>`<option value="${v.id}" ${project.stmgSpecific===v.id?'selected':''}>${e(v.title)}</option>`).join('')}</select></label><p class="notice">Les trois enseignements ci-dessus sont proposés au lycée. Systèmes d’information de gestion (SIG) existe dans l’offre nationale, dans d’autres établissements.</p></div>`;}
function renderTrackCompare(){
 if(comparatorKind()!=='stmg'){view.innerHTML=`${head('Mon parcours · mes choix','Comparer dans ma voie.','Les séries technologiques et les parcours professionnels ont leurs propres enseignements et conditions d’accès. Le choix de trois spécialités puis de deux concerne la voie générale.')}${comparePicker()}${currentPathPicker()}<div class="actions"><a class="btn primary" href="#voies">Découvrir les voies et les séries</a><a class="btn" href="#formations">Explorer des formations</a><a class="btn" href="#niveau">Les étapes de mon année</a></div>${localSnapshot()}${foot()}`;return;}
 view.innerHTML=`${head('STMG · préparer la terminale et la suite','Trois enseignements, plusieurs façons d’approfondir.','Compare ce que l’on y apprend, les activités proposées et les questions à poser. Ton choix ne t’enferme pas dans un seul domaine d’études.')}${comparePicker()}${currentPathPicker()}${stmgContext()}<div class="grid three">${STMG_SPECIFICS.map(v=>`<article class="card ${project.stmgSpecific===v.id?'tint':''}"><p class="eyebrow">Au lycée</p><h2>${e(v.title)}</h2><p>${e(v.text)}</p><p class="small muted">À demander : une activité type, les outils utilisés et la place du travail en groupe.</p>${btn('stmg-specific',project.stmgSpecific===v.id?'✓ Mon hypothèse':'+ Garder cette hypothèse',project.stmgSpecific===v.id?'primary':'',`data-id="${v.id}" aria-pressed="${project.stmgSpecific===v.id}"`)}</article>`).join('')}</div>${section('Et après la STMG ?')}<div class="grid two"><article class="card"><h3>Des diplômes à comparer</h3><p>BTS, BUT, prépa ECT, licences et écoles selon le projet et le dossier. Compare les contenus, le rythme, les stages, le coût et les conditions d’accès.</p><a class="btn primary" href="#formations">Rechercher des formations</a></article><article class="card paper"><h3>Trois BTS au lycée</h3><p>Comptabilité et gestion · Gestion des transports et logistique associée · Négociation et digitalisation de la relation client.</p><p class="small">Tu peux aussi explorer des formations ailleurs. Il n’y a pas de poursuite automatique dans le BTS du lycée.</p></article></div>${callout('Un choix à expliquer.','Ton enseignement spécifique enrichit ta préparation. Pour décider, confronte tes intérêts aux programmes et aux conseils des professeurs. Les formations supérieures examinent leurs propres critères.')}<div class="actions">${btn('save-track-scenario','Enregistrer cette hypothèse','primary')}<a class="btn" href="#projet">Continuer dans mon carnet</a>${external(VERIFIED_SOURCES[2][1],'Comprendre la STMG','btn ghost')}</div>${foot()}`;
}
async function downloadPDF(html,filename){
 const invalid=$('[data-budget]:invalid');if(invalid){invalid.reportValidity();toast('Corrige le montant invalide avant de télécharger ton PDF.');return;}
 if(exportBusy){toast('Ton PDF est en cours de préparation.');return;}
 exportBusy=true;toast('Préparation de ton PDF A4…');
 const controls=[...document.querySelectorAll('[data-action="project-print"],[data-action="print-guide"],[data-action="print-formation"]')];controls.forEach(b=>{b.disabled=true;b.setAttribute('aria-busy','true');});
 try{await exportPDF(html,filename);toast('Ton PDF A4 est prêt. Le fichier projet reste utile pour reprendre tes modifications.');}
 catch(err){toast('Le PDF n’a pas pu être créé. Réessaie avec une connexion ou utilise l’impression du navigateur depuis ton carnet.');console.error('Export PDF :',err);}
 finally{exportBusy=false;controls.forEach(b=>{b.disabled=false;b.removeAttribute('aria-busy');});}
}

function renderLevel(){const l=levelContent(project);
  view.innerHTML=`${head('Mon étape · un fil conducteur',l.title,l.intro)}${levelPicker()}${currentPathPicker()}${project.currentPath==='stmg'&&project.level!=='seconde'?stmgContext():''}<div class="steps">${l.steps.map(([title,text,check],i)=>`<article class="guide-step"><h3 class="step-title">${title}</h3><p class="muted small">${text}</p><label class="checkline"><input type="checkbox" data-check="${checkKey(i)}" ${project.checks[checkKey(i)]?'checked':''}><span>${check}</span></label></article>`).join('')}</div>${callout('Une prochaine action suffit.',`${l.prompt} Note ta réponse dans ton carnet ; tu pourras la faire évoluer.`)}<div class="actions"><a class="btn primary" href="#projet">Noter dans mon projet →</a><a class="btn" href="#specialites">Comparer mes choix</a>${external(URLS.calendrier,'Calendrier officiel','btn ghost')}</div>${project.level==='terminale'?`<div class="card paper" style="margin-top:24px"><h2>Ta campagne, tes dates.</h2><p class="small">Au 16 octobre 2026, le calendrier Parcoursup 2027 n’est pas encore publié. Prépare tes recherches dès maintenant et consulte le calendrier officiel dès sa publication. Les dates et délais affichés dans ton dossier feront référence. Les fiches du catalogue ci-dessous décrivent 2025.</p></div>`:''}${project.level==='premiere'?callout('Le bac se prépare aussi en première.','En voie générale et technologique, tu passes les épreuves anticipées de français et de mathématiques. L’épreuve de mathématiques concerne tous les élèves depuis juin 2026. Ton équipe te précise les modalités et le calendrier.') : ''}${section('Les bonnes ressources à cette étape')}${resourceSubset(l.resources.slice(0,4))}${foot()}`;
}

function pathwayCard(p){const selected=project.pathways.includes(p.id);return `<article class="card pathway-card ${selected?'selected':''}"><p class="eyebrow">${e(p.kicker)}</p><h2>${e(p.title)}</h2><p>${e(p.description)}</p><dl class="path-facts"><dt>Façon d’apprendre</dt><dd>${e(p.learning)}</dd><dt>Applications et projets</dt><dd>${e(p.projects)}</dd><dt>Après le bac</dt><dd>${e(p.after)}</dd></dl>${btn('pathway',selected?'✓ Voie gardée dans mon projet':'+ Garder cette voie à explorer',selected?'primary':'',`data-id="${p.id}" aria-pressed="${selected}"`)}</article>`;}
function techCard(s){const selected=project.techSeries===s.id;return `<article class="card tech-card ${selected?'selected':''}"><div class="row-between"><span class="pill">${e(s.title)}</span>${s.id==='stmg'?'<span class="pill green">À Ambroise Paré</span>':''}</div><h3>${e(s.name)}</h3><p class="small muted">${e(s.interests)}</p><div class="actions">${btn('tech-detail','Voir la fiche','compact',`data-id="${s.id}"`)}${btn('tech-save',selected?'✓ Dans mon projet':'+ Mon projet','compact ghost',`data-id="${s.id}" aria-pressed="${selected}"`)}</div></article>`;}
function openTech(id){const s=TECH_SERIES.find(x=>x.id===id);if(!s)return;openDialog(`<p class="eyebrow">Voie technologique · ${e(s.title)}</p><h2 id="dialog-title">${e(s.name)}</h2><div class="fact-grid"><div><strong>Présentation</strong><p>${e(s.interests)}</p></div><div><strong>Façon d’apprendre</strong><p>${e(s.learn)}</p></div><div><strong>Enseignements principaux</strong><p>${e(s.teach)}</p></div><div><strong>Projets et expérimentations</strong><p>${e(s.projects)}</p></div><div><strong>Poursuites d’études</strong><p>${e(s.after)}</p></div><div><strong>Exemples de domaines</strong><p>${e(s.domains)}</p></div></div>${callout('Condition ou point à vérifier',e(s.conditions),true)}<div class="actions">${btn('tech-save',project.techSeries===s.id?'✓ Série gardée dans mon projet':'+ Garder cette série','primary',`data-id="${s.id}"`)}${external(s.url,'Rechercher où cette série est proposée','btn')}</div><p class="source-line">Source pédagogique : Onisep ou ministère chargé de l’agriculture pour STAV · vérification le ${UPDATED}.</p>`);}
function renderPathways(){view.innerHTML=`${head('Après la seconde · ouvrir l’horizon','Quelles sont les possibilités après ma seconde ?','Voie générale, voie technologique et voie professionnelle sont trois façons différentes de construire la suite. Elles n’établissent aucune hiérarchie entre les élèves.')}
  <div class="grid three">${PATHWAYS.map(pathwayCard).join('')}</div>
  ${section('Comparer les voies')}<div class="table-wrap compare-paths"><table class="data-table"><caption>Des différences de pédagogie, pas un classement.</caption><thead><tr><th>Repère</th>${PATHWAYS.map(p=>`<th>${e(p.title)}</th>`).join('')}</tr></thead><tbody><tr><th>Nature des enseignements</th><td>Communs et spécialités disciplinaires</td><td>Communs et spécialités propres à une série</td><td>Généraux et professionnels</td></tr><tr><th>Théorie et concepts</th><td>Place importante, variable selon les spécialités</td><td>Reliés à des objets, secteurs et situations</td><td>Reliés aux activités et gestes professionnels</td></tr><tr><th>Applications concrètes</th><td>Présentes selon les disciplines</td><td>Études de cas, projets ou expérimentations fréquents</td><td>Mises en situation et périodes en milieu professionnel</td></tr><tr><th>Spécialisation</th><td>Progressive par trois puis deux spécialités</td><td>Progressive dans une série et ses enseignements</td><td>Organisée autour d’un domaine professionnel</td></tr><tr><th>Poursuites fréquentes</th><td>Ensemble du supérieur selon le projet</td><td>BTS, BUT et autres voies selon la série</td><td>Insertion ou poursuite, notamment en BTS selon le diplôme</td></tr></tbody></table></div>
  ${section('Les huit séries technologiques')}<p class="notice">La STMG est proposée à Ambroise Paré. Les autres séries doivent rester visibles : l’établissement fréquenté aujourd’hui ne limite pas l’horizon de l’élève.</p><div class="grid two">${TECH_SERIES.map(techCard).join('')}</div>
  <section class="reorientation" id="reorientation"><p class="eyebrow">Un autre chemin est possible</p><h2>Et si ma voie actuelle ne me convient plus ?</h2><p>Une réorientation peut permettre de rechercher un parcours davantage adapté à tes intérêts, à ta manière d’apprendre ou à ton projet. Ce n’est ni un échec ni une orientation par défaut.</p><div class="grid two">${REORIENTATION_STEPS.map(x=>`<article class="reorientation-step"><h3>${e(x.title)}</h3><p>${e(x.text)}</p></article>`).join('')}</div><label class="field">Mon hypothèse ou ma question<textarea data-field="reorientation" rows="3" maxlength="15000" placeholder="Ce que je voudrais changer, découvrir ou vérifier…">${e(project.reorientation)}</textarea></label><div class="actions">${btn('reorientation-save','Garder cette réflexion dans Mon projet','primary')}${external(URLS.apprentissage,'Explorer l’apprentissage','btn')}${external('https://www.onisep.fr/formation/apres-la-3-la-voie-professionnelle','Découvrir la voie professionnelle','btn')}</div></section>
  ${callout('Une passerelle se prépare avec des personnes.','Selon le moment de l’année, le niveau, les acquis et les places disponibles, les modalités diffèrent. Prends contact avec le professeur principal, le Psy-EN et l’établissement envisagé avant toute décision.')}${foot()}`;}
function scenarioCard(pair,index){const a=analyzeScenario(project.trio,pair,project.domainIds,DOMAIN_RULES,SPECIALTIES);const selected=pair.length===project.pair.length&&pair.every(id=>project.pair.includes(id));return `<article class="card scenario-card ${selected?'selected':''}"><p class="eyebrow">Possibilité ${String.fromCharCode(65+index)}</p><h3>${a.kept.map(e).join(' + ')}</h3><p class="small"><strong>Spécialité arrêtée :</strong> ${a.abandonedNames.map(e).join('')}</p><div class="recommendation coherent"><strong>${a.coherent.length?'Cohérent':'Possible'}</strong><p>${e(a.strengths[0])}</p></div><div class="recommendation vigilance"><strong>Point de vigilance</strong><p>${e(a.warnings[0])}</p></div>${a.options.map(o=>`<div class="recommendation option"><strong>${e(o.level)} · ${e(o.label)}</strong><details><summary>Pourquoi cette recommandation ?</summary><p>${e(o.why)}</p></details></div>`).join('')}<p class="small muted">${e(a.consequences)}</p><div class="actions">${btn('keep-pair',selected?'✓ Hypothèse retenue':'Choisir cette hypothèse',selected?'primary':'compact',`data-ids="${pair.join(',')}"`)}${btn('save-scenario','Enregistrer le scénario','compact ghost',`data-ids="${pair.join(',')}"`)}</div></article>`;}
function localProjectBlock(){const relevant=LOCAL_OFFERS.filter(o=>(!['math-comp','math-exp'].includes(o.id)||project.currentPath==='generale'||project.level==='seconde')&&project.domainIds.some(id=>o.domains.includes(id))&&(o.id!=='math-comp'||!project.pair.includes('maths'))&&(o.id!=='math-exp'||project.pair.includes('maths')));if(!relevant.length)return'';return `${section('Ce que mon lycée peut apporter à mon projet')}<p class="notice">Les propositions ci-dessous dépendent des domaines sélectionnés. Elles enrichissent un parcours mais ne garantissent pas une admission.</p><div class="grid two">${relevant.map(o=>`<article class="card local-offer"><span class="pill">${e(o.type)}</span><h3>${e(o.title)}</h3><p>${e(o.condition)}</p><details><summary>Pourquoi l’explorer ?</summary><p class="small">${e(o.why)}</p></details>${btn('local-option',project.options.includes(o.id)?'✓ Ajouté au projet':'+ Ajouter au projet','compact ghost',`data-id="${o.id}" aria-pressed="${project.options.includes(o.id)}"`)}</article>`).join('')}</div>`;}
function renderSpecialties(){if(comparatorKind()!=='generale'){renderTrackCompare();return;}const ids=project[specMode],limit=specMode==='trio'?3:2,pool=SPECIALTIES.filter(s=>specialtyScope==='national'||LOCAL_SPECIALTY_IDS.includes(s.id)||ids.includes(s.id)),available=specMode==='pair'&&project.trio.length===3?SPECIALTIES.filter(s=>project.trio.includes(s.id)):pool,pairings=project.trio.length===3?combinations(project.trio):[];
  view.innerHTML=`${head(project.level==='terminale'?'Terminale générale · mes enseignements':'Voie générale · mes possibilités',project.level==='terminale'?'Mes spécialités, mes pistes après le bac.':'Comparer mes spécialités, comprendre mes choix.',project.level==='terminale'?'Indique les deux spécialités que tu suis. Choisis des domaines, puis explore des formations et leurs critères actuels.':'Choisis trois spécialités pour explorer les trois paires possibles en terminale. Tu peux garder plusieurs hypothèses et en parler avec tes professeurs.')}
  ${comparePicker()}<div class="entry-switch"><a href="#specialites" class="card card-link"><p class="eyebrow">Entrée 1</p><h3>J’ai ces enseignements</h3><p class="small muted">Je pars de mon trio et j’explore ses trois paires.</p></a><a href="#domaines" class="card card-link"><p class="eyebrow">Entrée 2</p><h3>J’envisage ce projet</h3><p class="small muted">Je choisis d’abord un domaine puis je reviens comparer les parcours.</p></a></div>
  <div class="level-picker" role="group" aria-label="Étape du choix"><button data-action="spec-mode" data-id="trio" class="${specMode==='trio'?'selected':''}" aria-pressed="${specMode==='trio'}">1 · Mes trois spécialités</button><button data-action="spec-mode" data-id="pair" class="${specMode==='pair'?'selected':''}" aria-pressed="${specMode==='pair'}">2 · Mon hypothèse de terminale</button></div>
  <div class="selection-tools"><label class="scope-select">Les enseignements affichés<select data-specialty-scope><option value="local" ${specialtyScope==='local'?'selected':''}>Au lycée Ambroise Paré</option><option value="national" ${specialtyScope==='national'?'selected':''}>Explorer aussi l’offre nationale</option></select></label></div><div class="results-head"><strong>${ids.length} / ${limit} enseignements sélectionnés</strong>${btn('spec-clear','Effacer cette sélection','ghost compact')}</div><p class="notice">La liste locale reprend les spécialités référencées par Onisep. Les spécialités nationales hors lycée sont identifiées. Vérifie les combinaisons réellement organisées pour ta rentrée. Les séries technologiques se découvrent dans « Les voies possibles » et ne se résument pas à des trios de spécialités générales.</p>
  ${specMode==='pair'&&project.trio.length<3&&project.level!=='terminale'?callout('Commence par ton trio.','Tu peux saisir directement une paire. Pour comparer les trois scénarios à partir de ta première, renseigne aussi ton trio.',true):''}
  <div class="specialty-grid">${available.map(s=>`<button class="specialty ${ids.includes(s.id)?'selected':''}" data-action="specialty" data-id="${s.id}" aria-pressed="${ids.includes(s.id)}"><span class="pill ${LOCAL_SPECIALTY_IDS.includes(s.id)?'green':''}">${LOCAL_SPECIALTY_IDS.includes(s.id)?'Au lycée':'Offre nationale / autre établissement'}</span><strong>${e(s.short)}</strong><span class="small muted">${e(s.name===s.short?'':s.name)}</span><small>${e(s.text)}</small><span class="specialty-mark">${ids.includes(s.id)?'✓ Sélectionné':'+ Explorer'}</span></button>`).join('')}</div>
  ${section('Mon ou mes projets à confronter')}<p class="notice">Choisis plusieurs domaines si tu hésites. Les repères se recalculent. Ils ne prédisent jamais une admission.</p><div class="domain-choices">${DOMAINS.map(d=>`<button type="button" class="domain-chip ${project.domainIds.includes(d.id)?'selected':''}" data-action="domain-toggle" data-id="${d.id}" aria-pressed="${project.domainIds.includes(d.id)}">${e(d.title)}</button>`).join('')}</div>
  ${pairings.length?`${section('Les trois possibilités de terminale')}<div class="actions scenario-actions">${btn('compare-scenarios',showScenarioCompare?'Masquer la comparaison':'Comparer mes trois possibilités','primary')}</div><div class="scenario-grid ${showScenarioCompare?'comparison-open':''}">${pairings.map(scenarioCard).join('')}</div>`:callout('Trois choix, puis trois hypothèses.','Dès que ton trio est complet, l’application génère automatiquement les trois paires possibles.',false)}
  ${selectionIssue(project.trio.length===3?project.trio:project.pair,project.options)?callout('Combinaison à revoir',e(selectionIssue(project.trio.length===3?project.trio:project.pair,project.options)),true):''}${project.pair.length===2?`<div class="selection-summary"><p class="eyebrow">Hypothèse actuelle</p><h2>Tu envisages de conserver ${project.pair.map(id=>e(SPECIALTIES.find(s=>s.id===id)?.short??id)).join(' et ')} ${project.trio.length===3?'et d’arrêter ':''}${project.trio.filter(id=>!project.pair.includes(id)).map(id=>e(SPECIALTIES.find(s=>s.id===id)?.short??id)).join('')}.</h2><p>Ce choix reste modifiable dans Mon projet et peut être enregistré parmi trois scénarios.</p></div>`:''}
  ${localProjectBlock()}${callout('Possible, cohérent, fréquent, recommandé, nécessaire : cinq mots différents.','« Possible » décrit une ouverture juridique ou pratique. « Cohérent » signale des apprentissages en lien. « Fréquent » décrit une observation, jamais une obligation. « Recommandé » appelle une raison explicite. « Nécessaire » n’est utilisé que lorsqu’une règle confirmée l’impose.')}
  <div class="actions"><a class="btn accent" href="#projet">Continuer dans Mon projet</a>${external(URLS.horizons,'Approfondir avec Horizons21','btn')}${external(URLS.choix,'Conseils officiels','btn ghost')}</div>${foot()}`;
}
function renderDomains(){view.innerHTML=`${head('Projet → parcours','J’envisage un domaine : quels parcours explorer ?','Un domaine n’est ni un métier unique ni une combinaison obligatoire. Choisis-en un ou plusieurs, découvre différentes voies puis confronte-les à tes enseignements.')}
  <div class="grid two">${DOMAINS.map(d=>`<article class="card ${project.domainIds.includes(d.id)?'domain-saved':''}"><span class="card-icon">${icon(d.icon)}</span><h2>${d.title}</h2><p class="eyebrow">${d.verb}</p><p class="muted small">${d.description}</p><div class="actions">${btn('domain','Explorer ce domaine →','',`data-id="${d.id}"`)}${btn('domain-toggle',project.domainIds.includes(d.id)?'✓ Dans mon projet':'+ Mon projet','ghost',`data-id="${d.id}" aria-pressed="${project.domainIds.includes(d.id)}"`)}</div></article>`).join('')}</div>
  ${project.domainIds.length?`<div class="selection-summary"><p class="eyebrow">Prochaine étape</p><h2>${project.domainIds.length} domaine${project.domainIds.length>1?'s':''} à confronter à plusieurs parcours.</h2><p>L’application ne cherche pas une combinaison unique. Elle compare les appuis, les vigilances et les options à examiner.</p><a class="btn primary" href="#specialites">Comparer mes parcours →</a></div>`:''}
  ${callout('Tu as le droit de ne pas encore savoir.','Choisis deux domaines par curiosité, même très différents. Tu pourras les retirer, les comparer et en ajouter d’autres.')}${section('Comprendre les diplômes')}${resourceSubset(['schema','reconnaissance'])}${foot()}`;}
function openDialog(html){$('#dialog-content').innerHTML=html;if(!dialog.open)dialog.showModal();dialog.scrollTop=0;}
function openDomain(id){const d=DOMAINS.find(x=>x.id===id);if(!d)return;
  openDialog(`<p class="eyebrow">Un domaine, plusieurs parcours</p><h2 id="dialog-title">${d.title}</h2><p>${d.description}</p><div class="card tint"><h3>Des voies à découvrir</h3><p>${d.tracks}</p></div>${section('Trois questions pour aller plus loin')}<ul class="compact-list">${d.questions.map(q=>`<li>${q}</li>`).join('')}</ul>${callout('Le point à vérifier',d.warning,true)}<p><strong>Une action concrète.</strong> ${d.action}</p><div class="actions">${btn('domain-search','Chercher des formations','primary',`data-id="${d.id}"`)}${btn('add-domain-action','Ajouter cette action au projet','',`data-id="${d.id}"`)}</div>${d.id==='sante'?`${callout('Études de santé · préparer 2027',e(HEALTH_UPDATE),true)}<p class="notice">Ces filtres ouvrent les fiches historiques de 2025.</p><div class="actions" style="margin-top:14px">${['PASS','Licence_Las','IFSI'].map(f=>btn('family-search',e(FAMILY_LABELS[f]),'compact',`data-id="${f}"`)).join('')}</div>`:''}${section('Pour vérifier et approfondir')}${resourceSubset(d.resources)}<p class="source-line">Les liens entre disciplines et domaines sont des repères pédagogiques, non un modèle d’admission.</p>`);
}
function openGuide(id){const g=GUIDES.find(x=>x.id===id);if(!g)return;openDialog(`<p class="eyebrow">Fiche pratique · Mon parcours</p><h2 id="dialog-title">${g.title}</h2><p class="muted">${g.subtitle}</p><ol class="compact-list">${g.items.map(t=>`<li>${e(t)}</li>`).join('')}</ol>${callout('À retenir',g.end)}<div class="actions">${btn('print-guide','Télécharger le PDF A4','primary',`data-id="${g.id}"`)}<a class="btn" data-close-dialog href="#projet">Prendre des notes dans mon projet</a></div>${section('Ressources associées')}${resourceSubset(g.resources)}`);}
async function loadData(){if(dataset)return dataset;if(!dataPromise)dataPromise=fetch('./formations.json').then(r=>{if(!r.ok)throw new Error('Chargement indisponible');return r.json();}).then(d=>{if(d.meta?.session!==2025||!Array.isArray(d.records))throw new Error('Données non reconnues');d.records.forEach(r=>{r._search=normalize([r.title,r.school,r.city,r.department,r.family,r.detail].join(' '));});dataset=d;return d;}).catch(err=>{dataPromise=null;throw err;});return dataPromise;}
async function renderFormations(){view.innerHTML=`${head('Observer l’historique · vérifier le présent','Les formations, en clair.','Cherche une formation, compare ses repères et garde ce qui t’intéresse dans ton projet. Les données ci-dessous décrivent 2025, hors apprentissage ; la fiche Parcoursup fait référence pour ta session.')}<div id="formation-interface"><p class="loading">Chargement du catalogue national (environ 8 Mo)…</p></div>${foot()}`;
  try{await loadData();if(route!=='formations')return;const specialtySummary=project.pair.length?project.pair.map(id=>SPECIALTIES.find(s=>s.id===id)?.short??id).join(' + '):'non renseignées';$('#formation-interface').innerHTML=`<div class="card terminal-context"><p class="eyebrow">Mon contexte d’exploration</p><p><strong>Spécialités ou enseignements :</strong> ${e(specialtySummary)}<br><strong>Domaines favoris :</strong> ${project.domainIds.map(id=>e(DOMAINS.find(d=>d.id===id)?.title??id)).join(' · ')||'non renseignés'}</p><p class="notice">Ces informations ouvrent des recherches mais ne filtrent jamais automatiquement une formation. Une spécialité fréquemment observée chez les admis n’est pas pour autant obligatoire.</p><div class="domain-choices">${project.domainIds.map(id=>DOMAINS.find(d=>d.id===id)).filter(Boolean).map(d=>btn('domain-search','Explorer '+e(d.title),'compact',`data-id="${d.id}"`)).join('')}<a class="btn compact ghost" href="#domaines">Modifier mes domaines</a></div></div><div class="actions" style="margin:20px 0">${external(URLS.carte,'Carte officielle · session en cours','btn primary')}${external(URLS.apprentissage,'Chercher en apprentissage','btn')}${btn('guide','Comprendre ces chiffres','ghost',`data-id="stats"`)}</div>${callout('D’abord la session actuelle.','Ce catalogue sert à découvrir et à comparer des repères de 2025. L’offre actuelle, les frais, les conditions et les dates se vérifient sur la carte officielle. Pour la santé, une réforme avec la licence portail santé est annoncée pour 2027.',true)}<div class="filters"><label class="field search">Formation, ville ou établissement<input type="search" id="formation-q" data-filter="q" value="${e(formationFilters.q)}" placeholder="Ex. droit, Laval, biologie…" maxlength="150"></label><label class="field">Académie d’accueil<select data-filter="academy"><option value="">Toute la France</option>${[...new Set(dataset.records.map(r=>r.academy))].filter(Boolean).sort((a,b)=>a.localeCompare(b,'fr')).map(v=>`<option ${v===formationFilters.academy?'selected':''} value="${e(v)}">${e(v)}</option>`).join('')}</select></label><label class="field">Type de formation<select data-filter="family"><option value="">Tous les types</option>${Object.entries(FAMILY_LABELS).map(([v,l])=>`<option value="${e(v)}" ${v===formationFilters.family?'selected':''}>${l}</option>`).join('')}</select></label><label class="field">Statut de l’établissement<select data-filter="status"><option value="">Tous les statuts</option>${[...new Set(dataset.records.map(r=>r.status))].filter(Boolean).sort().map(v=>`<option value="${e(v)}" ${formationFilters.status===v?'selected':''}>${e(v)}</option>`).join('')}</select></label><label class="checkline"><input type="checkbox" data-filter="savedOnly" ${formationFilters.savedOnly?'checked':''}><span>Mes pistes uniquement</span></label>${btn('reset-filters','Réinitialiser','compact ghost')}</div><div id="formation-results"></div><div id="compare-bar"></div>`;renderFormationResults();
  }catch{if(route!=='formations')return;$('#formation-interface').innerHTML=`<div class="empty"><h2>Le catalogue n’a pas pu être chargé.</h2><p>Tes écrits restent dans ton carnet. Réessaie ou poursuis sur la carte officielle.</p><div class="actions">${btn('retry-data','Réessayer','primary')}${external(URLS.carte,'Ouvrir Parcoursup','btn')}</div></div>`;}}
function formationCard(r){const saved=project.choices.some(c=>c.id==='psup-'+r.id);return `<article class="card formation"><div class="tags"><span class="pill">${e(FAMILY_LABELS[r.family]??r.family)}</span><span class="pill green">2025</span></div><div><h3>${e(r.title)}</h3><p class="place">${e(r.school)}<br>${e(r.city)} · ${e(r.academy)}</p></div><div class="metrics"><div><strong>${num(r.places)}</strong><span>places</span></div><div><strong>${num(r.candidates)}</strong><span>candidats en phase principale</span></div><div><strong>${pct(r.access)}</strong><span>taux d’accès publié</span></div></div><p class="notice">${e(r.status)} · ${e(r.selectivity)}</p><div class="actions">${btn('formation','Voir la fiche','compact',`data-id="${r.id}"`)}${btn('save-formation',saved?'✓ Dans mon projet':'+ Mon projet','compact ghost',`data-id="${r.id}" aria-pressed="${saved}" aria-label="${saved?'Retirer du projet':'Ajouter au projet'} : ${e(r.title)} à ${e(r.school)}"`)}</div><label class="checkline"><input type="checkbox" data-compare="${r.id}" ${compare.includes(r.id)?'checked':''}><span>Comparer cette formation</span></label></article>`;}
function renderFormationResults(){if(!dataset||!$('#formation-results'))return;const filtered=filterFormations(dataset.records,{...formationFilters,savedIds:project.choices.map(c=>c.id.replace(/^psup-/,''))});const totalPages=Math.max(1,Math.ceil(filtered.length/18));page=Math.min(Math.max(1,page),totalPages);
  $('#formation-results').innerHTML=`<div class="results-head"><p role="status" aria-live="polite" style="margin:0"><strong>${num(filtered.length)} formation${filtered.length>1?'s':''}</strong> · classement alphabétique, sans recommandation automatique.</p><span>${dataset.meta.session} · hors apprentissage</span></div>${filtered.length?`<div class="grid two">${filtered.slice((page-1)*18,page*18).map(formationCard).join('')}</div><div class="pagination">${btn('page-prev','← Précédent','compact',page===1?'disabled':'')}<span class="small">${page} / ${totalPages}</span>${btn('page-next','Suivant →','compact',page===totalPages?'disabled':'')}</div>`:`<div class="empty"><h3>Aucune fiche avec ces critères.</h3><p>Élargis l’académie, change de mot-clé ou consulte la carte officielle : ce catalogue n’est pas l’offre en temps réel.</p>${btn('reset-filters','Effacer les filtres','primary')}</div>`}<p class="source-line">${external(URLS.dataset,'Source : Parcoursup — traitement SIES')} · Licence Ouverte 2.0 · actualisation du jeu le 9 mars 2026, extrait le 8 septembre 2026.<br>« Académie » situe l’établissement d’accueil. « Non publié » signifie donnée manquante, pas zéro. Les listes peuvent inclure des regroupements de formations.</p>`;renderCompareBar();}
function renderCompareBar(){const bar=$('#compare-bar');if(!bar)return;bar.innerHTML=compare.length?`<div class="compare-bar"><span><strong>${compare.length} / 3</strong> formations à comparer</span><div class="actions">${btn('compare-open','Comparer →','compact')}${btn('compare-clear','Vider','compact')}</div></div>`:'';}
function findFormation(id){return dataset?.records.find(r=>r.id===id);}
function openFormation(id){const r=findFormation(id);if(!r)return;const saved=project.choices.some(c=>c.id==='psup-'+r.id);openDialog(`<p class="eyebrow">Historique Parcoursup 2025 · hors apprentissage</p><h2 id="dialog-title">${e(r.title)}</h2><p>${e(r.school)} · ${e(r.city)}<br><span class="small muted">${e(r.status)} · ${e(r.selectivity)}</span></p><div class="card"><div class="metrics"><div><strong>${num(r.places)}</strong><span>places en 2025</span></div><div><strong>${num(r.candidates)}</strong><span>candidats · phase principale</span></div><div><strong>${pct(r.access)}</strong><span>taux d’accès publié</span></div></div><div class="metrics"><div><strong>${num(r.proposals)}</strong><span>candidats ayant reçu une proposition · campagne</span></div><div><strong>${num(r.accepted)}</strong><span>candidats ayant accepté · campagne</span></div><div><strong>${num(r.newbac)}</strong><span>néo-bacheliers parmi les acceptations</span></div></div></div>
  ${callout('Le taux d’accès n’est pas ta chance personnelle.','C’est un indicateur de la campagne 2025 basé sur les classements et les groupes d’appel. Le rapport entre acceptations et candidatures n’est pas ce taux.',true)}
  <details class="card"><summary>Profils des personnes ayant accepté en 2025</summary><div class="table-wrap"><table class="data-table"><tbody>${[['Néo-bacheliers généraux',num(r.general)],['Néo-bacheliers technologiques',num(r.techno)],['Néo-bacheliers professionnels',num(r.pro)],['Boursiers parmi les néo-bacheliers admis',pct(r.scholarship)],['Femmes parmi l’ensemble des admis',pct(r.women)]].map(([k,v])=>`<tr><th>${k}</th><td>${v}</td></tr>`).join('')}</tbody></table></div><p class="notice" style="margin-top:14px">Ces profils ne sont ni des conditions d’accès ni un classement social. Les petits effectifs appellent de la prudence. L’extrait ne contient pas les spécialités ou moyennes des candidats.</p></details>
  ${section('Avant d’en faire une candidature')}<ul class="compact-list"><li>Vérifie que le cursus existe pour ta session et lis son programme.</li><li>Consulte les attendus, critères, frais et modalités d’inscription actuels.</li><li>Explore les profils observés sans les transformer en conditions obligatoires.</li><li>Vérifie les poursuites d’études, débouchés et contacts sur la fiche officielle.</li></ul><div class="actions">${external(r.url,'Fiche Parcoursup officielle','btn primary')}${btn('save-formation',saved?'✓ Dans mon projet':'+ Ajouter au projet','',`data-id="${r.id}"`)}${btn('print-formation','Exporter cette fiche en PDF','',`data-id="${r.id}"`)}${btn('guide','Comment lire une fiche ?','ghost',`data-id="fiche"`)}</div><p class="source-line">Le lien provient de l’export 2025 ; s’il a changé, ${external(URLS.carte,'retrouve le cursus dans la carte actuelle')}. ${external(URLS.dataset,'Méthode et données sources')}</p>`);}
function openCompare(){const rows=compare.map(findFormation).filter(Boolean);if(!rows.length)return;const line=(name,fn)=>`<tr><th scope="row">${name}</th>${rows.map(r=>`<td>${fn(r)}</td>`).join('')}</tr>`;openDialog(`<p class="eyebrow">Comparer pour poser de meilleures questions</p><h2 id="dialog-title">Ce qui change d’une formation à l’autre.</h2><p class="notice">Historique 2025 · ces différences ne constituent pas un classement.</p><div class="table-wrap"><table class="data-table"><thead><tr><th>Repère</th>${rows.map(r=>`<th scope="col">${e(r.title)}<br><span class="small">${e(r.school)}</span></th>`).join('')}</tr></thead><tbody>${line('Lieu',r=>e(r.city))}${line('Statut',r=>e(r.status))}${line('Places',r=>num(r.places))}${line('Candidats · phase principale',r=>num(r.candidates))}${line('Taux d’accès publié',r=>pct(r.access))}${line('Acceptations · campagne',r=>num(r.accepted))}${line('À vérifier',()=> 'Contenus, rythme, critères, coût total, aides et possibilités de poursuite.')}${line('Fiche officielle',r=>external(r.url,'Consulter'))}</tbody></table></div>${callout('Ce qui compte aussi ne tient pas dans ce tableau.','Demande-toi dans quel cadre tu apprends bien, où tu pourrais vivre et à qui tu pourrais demander de l’aide.')}`);}
function renderResources(){view.innerHTML=`${head('Une bibliothèque pour ouvrir des portes','De quoi nourrir tes idées.','Des ressources publiques sélectionnées et des fiches pratiques pour passer de la recherche à l’action. Les liens externes ouvrent un nouvel onglet ; certains services demandent leur propre connexion.')}<div class="filters"><label class="field search">Rechercher<input type="search" data-resource-filter="q" value="${e(resourceFilters.q)}" placeholder="Ex. santé, bourse, vidéo, stage…" maxlength="150"></label><label class="field">Sujet<select data-resource-filter="category"><option value="">Tous les sujets</option>${[...new Set(RESOURCES.map(r=>r.category))].sort((a,b)=>a.localeCompare(b,'fr')).map(c=>`<option value="${e(c)}" ${c===resourceFilters.category?'selected':''}>${e(c)}</option>`).join('')}</select></label><label class="field">Niveau<select data-resource-filter="level"><option value="">Tous les niveaux</option>${Object.entries(LEVELS).map(([id,l])=>`<option value="${id}" ${id===resourceFilters.level?'selected':''}>${l.label}</option>`).join('')}</select></label><label class="checkline"><input type="checkbox" data-resource-filter="savedOnly" ${resourceFilters.savedOnly?'checked':''}><span>Mes ressources repérées</span></label></div><div id="resource-results"></div>${section('Les fiches pratiques de Mon parcours')}<p class="notice">À lire ici ou à imprimer pour préparer un échange. Ces fiches sont des méthodes de travail, pas des consignes réglementaires.</p><div class="grid two">${GUIDES.map(g=>`<article class="card paper"><p class="eyebrow">Fiche pratique</p><h3>${g.title}</h3><p class="muted small">${g.subtitle}</p>${btn('guide','Lire la fiche →','compact',`data-id="${g.id}"`)}</article>`).join('')}</div>${foot()}`;renderResourceResults();}
function renderResourceResults(){const holder=$('#resource-results');if(!holder)return;const tokens=normalize(resourceFilters.q).split(/\s+/).filter(Boolean);const rows=RESOURCES.filter(r=>(!resourceFilters.category||r.category===resourceFilters.category)&&(!resourceFilters.level||r.level==='tous'||r.level===resourceFilters.level)&&(!resourceFilters.savedOnly||project.resources.includes(r.id))&&tokens.every(t=>normalize([r.title,r.description,r.provider,r.category,r.type].join(' ')).includes(t)));holder.innerHTML=`<p class="small muted" role="status" aria-live="polite">${rows.length} ressource${rows.length>1?'s':''} · sélection préparée le ${UPDATED}</p>${rows.length?`<div class="grid two">${rows.map(resourceCard).join('')}</div>`:`<div class="empty"><h3>Pas de ressource avec ces critères.</h3><p>Change de mot-clé ou élargis les filtres.</p>${btn('resource-reset','Voir toutes les ressources','primary')}</div>`}`;}

const field=(key,label,placeholder='',rows=3)=>`<label class="field">${label}<textarea data-field="${key}" rows="${rows}" maxlength="15000" placeholder="${e(placeholder)}">${e(project[key])}</textarea></label>`;
const input=(key,label,placeholder='')=>`<label class="field">${label}<input data-field="${key}" maxlength="${key==='title'?180:100}" value="${e(project[key])}" placeholder="${e(placeholder)}"></label>`;
const choiceStatuses=['À explorer','À approfondir','Candidature envisagée','Candidature confirmée','Proposition reçue','Proposition acceptée','Non retenue'];
function budgetOutput(){const b=budgetSummary(project.budget);if(!b.provided&&!b.incomeProvided&&!b.oneoffProvided)return '<p class="small">Renseigne tes estimations pour voir les dépenses mensuelles. Les cases vides restent des informations manquantes.</p>';return `<p><strong>${num(b.monthly)} €</strong> de dépenses mensuelles saisies</p><p class="small">${b.provided} / 4 postes renseignés — estimation ${b.provided<4?'partielle':'à vérifier'}. ${b.incomeProvided?`Ressources estimées : ${num(b.income)} €.<br>Écart dépenses − ressources : <b>${num(b.gap)} €</b> ${b.gap>0?'à financer avec des solutions à rechercher.':'(sous réserve des dépenses et ressources confirmées).'}`:'Ressources non renseignées : équilibre non évalué.'}<br>Frais ponctuels saisis : ${num(b.oneoff)} €. Une aide estimée n’est pas encore accordée.</p>`;}
function renderChoices(){return project.choices.length?project.choices.map((c,i)=>`<article class="project-choice"><div class="row-between"><div><h3>${e(c.title)}</h3><p class="small muted">${e(c.school)}${c.city?' · '+e(c.city):''}<br>${e(c.source||'Piste ajoutée manuellement')}</p></div>${btn('remove-choice','Retirer','compact danger',`data-index="${i}" aria-label="Retirer ${e(c.title)}"`)}</div><label class="field">Où j’en suis avec cette piste<select data-choice="${i}" data-key="status">${choiceStatuses.map(s=>`<option ${c.status===s?'selected':''}>${s}</option>`).join('')}</select></label><label class="field">Ce qui me donne envie<textarea data-choice="${i}" data-key="reason" maxlength="6000" rows="2" placeholder="Un enseignement précis, une façon d’apprendre…">${e(c.reason)}</textarea></label><label class="field">Ce que je dois vérifier<textarea data-choice="${i}" data-key="question" maxlength="3000" rows="2" placeholder="Une question de contenu, de logement, de frais…">${e(c.question)}</textarea></label><details><summary>Rédiger une motivation pour cette formation</summary><p class="notice">Seulement si elle est demandée. Vérifie la consigne et la limite sur la fiche de ta session.</p><label class="field">Mon brouillon<textarea data-choice="${i}" data-key="motivation" maxlength="15000" rows="5" placeholder="Je m’intéresse à… J’ai découvert… J’aimerais approfondir…">${e(c.motivation||'')}</textarea></label></details>${external(c.url,'Ouvrir la fiche source')}</article>`).join(''):`<div class="empty"><h3>Tout commence par une piste.</h3><p>Ajoute une formation depuis l’explorateur ou renseigne une piste personnelle, y compris hors Parcoursup ou en apprentissage.</p></div>`;}
function renderTasks(){return project.tasks.map((t,i)=>`<div class="todo-row"><input type="checkbox" data-task="${i}" data-key="done" ${t.done?'checked':''} aria-label="Action ${i+1} terminée"><label><span class="sr-only">Action ${i+1}</span><input data-task="${i}" data-key="text" value="${e(t.text)}" maxlength="1200" placeholder="Ma prochaine démarche"></label><label class="todo-date"><span class="sr-only">Échéance de l’action ${i+1}</span><input type="date" data-task="${i}" data-key="date" value="${e(t.date)}"></label>${btn('remove-task','×','danger remove-task',`data-index="${i}" aria-label="Retirer l’action ${i+1}"`)}</div>`).join('');}
function renderScenarios(){return project.scenarios.length?`<div class="scenario-saved-list">${project.scenarios.map((s,i)=>`<article class="scenario-saved"><div class="row-between"><label class="field">Nom du scénario<input data-scenario="${i}" data-key="title" value="${e(s.title)}" maxlength="120"></label>${btn('remove-scenario','Retirer','compact danger',`data-index="${i}"`)}</div><p class="small"><strong>${s.pair.length?s.pair.map(id=>e(SPECIALTIES.find(v=>v.id===id)?.short??id)).join(' + '):s.techSeries?e(TECH_SERIES.find(v=>v.id===s.techSeries)?.title??s.techSeries):e(s.pathway||'Parcours à préciser')}</strong><br>${s.domainIds.map(id=>e(DOMAINS.find(v=>v.id===id)?.title??id)).join(' · ')||'Domaines à préciser'}</p><label class="field">Notes sur cette hypothèse<textarea data-scenario="${i}" data-key="notes" rows="2" maxlength="6000">${e(s.notes)}</textarea></label>${btn('load-scenario','Reprendre cette hypothèse','compact',`data-index="${i}"`)}</article>`).join('')}</div>`:`<div class="empty"><h3>Aucun scénario enregistré.</h3><p>Depuis « Comparer mes choix », garde jusqu’à trois hypothèses différentes puis reviens les annoter ici.</p></div>`;}
function renderProject(scrollTarget){
  view.innerHTML=`${head('Écrire, faire évoluer, en parler','Mon projet prend forme.','Ce carnet est à toi. Tu choisis ce que tu écris et ce que tu partages. Tu peux revenir sur tes choix à tout moment ; les rubriques ne sont pas une liste d’obligations.')}
  <div class="project-layout"><div>
  <section class="card project-section" id="project-about"><p class="eyebrow">01 · Mon point de départ</p><h2>Ce qui me fait avancer</h2><p class="notice">Prénom ou pseudonyme facultatif. N’indique ni INE, adresse, coordonnées, revenus familiaux détaillés ni information médicale.</p><div class="grid two">${input('name','Prénom ou pseudonyme','Facultatif')}${input('classroom','Classe','Facultatif')}</div>${input('title','Titre de mon projet','Un titre à moi')}${levelPicker()}${currentPathPicker()}${field('interests','Ce que j’aime apprendre et faire','En cours, dans mes activités, quand je suis curieux…')}${field('strengths','Mes points d’appui, avec des exemples','Je sais expliquer, organiser, chercher, créer… Par exemple…')}${field('values','Ce qui compte pour moi','Travailler en équipe, comprendre, être utile, créer, préserver du temps…')}<h3>Domaines favoris</h3><div class="domain-choices">${DOMAINS.map(d=>`<button type="button" class="domain-chip ${project.domainIds.includes(d.id)?'selected':''}" data-action="domain-toggle" data-id="${d.id}" aria-pressed="${project.domainIds.includes(d.id)}">${e(d.title)}</button>`).join('')}</div></section>
  <section class="card project-section" id="project-specialties"><p class="eyebrow">02 · Mes parcours et scénarios</p><h2>Mes choix restent modifiables</h2><p class="small"><strong>Voies explorées :</strong> ${project.pathways.map(id=>e(PATHWAYS.find(v=>v.id===id)?.title??id)).join(' · ')||'Pas encore renseignées'}<br><strong>Trio exploré :</strong> ${project.trio.map(id=>e(SPECIALTIES.find(s=>s.id===id)?.short??id)).join(' + ')||'Pas encore renseigné'}<br><strong>Paire envisagée :</strong> ${project.pair.map(id=>e(SPECIALTIES.find(s=>s.id===id)?.short??id)).join(' + ')||'Pas encore renseignée'}<br><strong>Enseignement spécifique STMG :</strong> ${e(STMG_SPECIFICS.find(v=>v.id===project.stmgSpecific)?.title??'À explorer')}<br><strong>Série technologique explorée :</strong> ${e(TECH_SERIES.find(v=>v.id===project.techSeries)?.title??'Pas encore renseignée')}<br><strong>Options et dispositifs :</strong> ${project.options.map(id=>e(LOCAL_OFFERS.find(v=>v.id===id)?.title??id)).join(' · ')||'Aucun pour le moment'}</p><div class="actions"><a href="#voies" class="btn compact">Explorer les voies</a><a href="#specialites" class="btn compact">Comparer les spécialités</a></div>${field('specialtyReason','Pourquoi ces choix ? Quels points travailler ?','Mes intérêts, ma progression, les conseils reçus, une hésitation…')}${field('option','Autre option ou dispositif à préciser','À discuter avec le lycée ; toutes les options ne sont pas proposées partout.')}<h3>Mes scénarios A, B et C</h3>${renderScenarios()}</section>
  <section class="card project-section" id="project-choices"><p class="eyebrow">03 · Mes possibilités</p><h2>Des pistes, pas encore des cases</h2>${field('target','Mon idée du moment','Un domaine, un diplôme, un métier… ou ce que j’aimerais découvrir.') }<div class="actions"><a href="#formations" class="btn primary">Explorer les formations</a>${btn('manual-choice','Ajouter une piste personnelle')}</div><p class="notice" style="margin-top:13px">Les états ci-dessous sont renseignés par toi. Aucune connexion à ton dossier Parcoursup n’est effectuée. Les pistes ne sont pas ordonnées comme des vœux officiels.</p>${renderChoices()}<label class="field">Établissements repérés, un par ligne<textarea data-establishments rows="3" maxlength="12000" placeholder="Nom de l’établissement · ville">${e(project.establishments.join('\n'))}</textarea></label></section>
  <section class="card project-section" id="project-voice"><p class="eyebrow">04 · Mes expériences, ma voix</p><h2>Ce que je peux raconter</h2>${field('experiences','Expériences, lectures et découvertes','Une rencontre, un stage, un projet, une responsabilité, une vidéo ou une lecture : ce que j’en ai appris.',5)}${field('motivation','Mon texte personnel de présentation','Ce qui m’intéresse, ce que j’ai découvert et ce que je souhaite approfondir. Écris avec tes mots.',7)}<p class="notice" data-count-for="motivation"></p>${btn('guide','M’aider à écrire sans écrire à ma place','ghost',`data-id="motivation"`)}</section>
  <section class="card project-section" id="project-life"><p class="eyebrow">05 · Les conditions pour réussir</p><h2>Une vie étudiante possible</h2>${field('mobility','Mobilité, logement et organisation','Les villes envisageables, les temps de trajet, une solution de logement à explorer…')}${field('support','Les aides ou accompagnements à rechercher','Un rendez-vous, un financement à vérifier, une question à poser au référent — sans détail sensible.')}<details><summary>Faire une première estimation de budget</summary><p class="notice">Facultatif, en euros. Saisis seulement des estimations de dépenses et de ressources globales. Cases vides = non renseignées, pas un budget équilibré.</p><div class="grid two">${[['rent','Logement / mois'],['food','Repas / mois'],['transport','Transport / mois'],['other','Autres dépenses / mois'],['income','Ressources estimées / mois'],['oneoff','Frais ponctuels de rentrée']].map(([k,label])=>`<label class="field">${label}<input type="number" min="0" max="100000" step="0.01" inputmode="decimal" data-budget="${k}" value="${e(project.budget[k])}" placeholder="Non renseigné"></label>`).join('')}</div><div class="budget-result" id="budget-output">${budgetOutput()}</div><div class="actions">${external(URLS.crous,'Simulateur officiel de bourse','btn compact')}${external(URLS.bourses,'Préparer le DSE','btn compact')}</div></details></section>
  <section class="card project-section" id="project-actions"><p class="eyebrow">06 · Mes prochains pas</p><h2>Repartir avec une action</h2>${field('questions','Les questions que je veux poser','Ce que j’aimerais éclaircir avec un professeur, le Psy-EN ou un étudiant…')}${field('nextStep','Ma prochaine action concrète','Ex. lire deux programmes de licence et prendre un rendez-vous.')}${field('meeting','Ce que je retiens d’un échange','La date, ce qui m’a aidé, ce qui reste à explorer — sans coordonnées personnelles.')}<h3>Ma liste de démarches</h3><p class="notice">Échéances personnelles, sans notification automatique. Pour Parcoursup, vérifie les dates dans ton dossier.</p>${renderTasks()}<div class="actions">${btn('add-task','+ Ajouter une démarche','compact')}${btn('seed-tasks','Ajouter la checklist proposée','compact ghost')}</div><div class="source-line">${external(URLS.calendrier,'Calendrier officiel')}</div></section>
  ${project.resources.length?`<section class="card project-section"><p class="eyebrow">Pour poursuivre</p><h2>Mes ressources repérées</h2><ul class="compact-list">${project.resources.map(id=>RESOURCES.find(r=>r.id===id)).filter(Boolean).map(r=>`<li>${external(r.url,r.title)}</li>`).join('')}</ul><a href="#ressources">Modifier mes repères →</a></section>`:''}
  </div><aside class="project-aside"><div class="card"><p class="eyebrow">Mon carnet</p><h3>À ton rythme.</h3><div class="progress-track" aria-hidden="true"><span id="progress-bar"></span></div><p class="small" id="project-progress"></p><p class="notice">Un repère d’écriture, jamais une note.</p>${btn('project-preview','Voir mon projet','primary')}${btn('project-print','Télécharger le PDF A4')}${btn('project-browser-print','Imprimer avec le navigateur','ghost compact')}${btn('project-export','Télécharger mon fichier')}${btn('import','Reprendre un fichier','ghost')}<p class="notice">Le fichier .json est ta copie à conserver et à réimporter pour continuer à modifier. Le PDF sert à lire ou partager.</p><label class="checkline"><input id="draft-consent" type="checkbox" ${draftEnabled?'checked':''}><span>Garder un brouillon de secours sur cet appareil personnel</span></label><p class="save-state" id="save-state" role="status"></p><p class="notice">Pas de synchronisation entre appareils. Sur un poste partagé, laisse cette option décochée et garde ton fichier dans un emplacement privé.</p><nav class="project-index" aria-label="Rubriques du projet">${[['about','01 · Moi'],['specialties','02 · Enseignements'],['choices','03 · Formations'],['voice','04 · Expériences'],['life','05 · Vie étudiante'],['actions','06 · Actions']].map(([id,label])=>`<a href="#projet" data-scroll="project-${id}">${label}</a>`).join('')}</nav>${btn('clear-project','Effacer ce carnet','compact danger')}<a href="#aide" class="small" style="display:block;margin-top:15px">Comment conserver mon travail ?</a></div></aside></div>${foot()}`;
  updateProjectIndicators();if(scrollTarget)$('#'+scrollTarget)?.scrollIntoView({behavior:'smooth'});
}
function renderHelp(){view.innerHTML=`${head('Mode d’emploi · sources · confidentialité','Tu gardes la main.','Cet espace aide à préparer tes choix et tes échanges. Il ne remplace ni ton dossier Parcoursup, ni les conseils de ton équipe éducative.')}<div class="grid three"><article class="card"><p class="card-number">01</p><h3>Explore</h3><p class="small muted">Choisis ton niveau, teste des enseignements, découvre des domaines et compare les formations.</p></article><article class="card"><p class="card-number">02</p><h3>Écris à ta façon</h3><p class="small muted">Ajoute des pistes à ton projet, explique ce qui t’attire et note les questions à poser.</p></article><article class="card"><p class="card-number">03</p><h3>Conserve et échange</h3><p class="small muted">Télécharge ton fichier pour le reprendre. Imprime ou enregistre un PDF pour un échange avec un adulte.</p></article></div>
  ${section('Les questions pratiques')}<div class="faq">${[
  ['Comment modifier et conserver mon projet ?','Ouvre « Mon carnet » et saisis ton texte. « Télécharger mon fichier » produit un fichier .json que tu conserves dans un endroit privé. Avec « Reprendre un fichier », tu peux le réimporter sur cet appareil ou un autre. Une confirmation est demandée avant de remplacer le carnet ouvert.'],
  ['Comment obtenir un PDF ?','Dans « Mon carnet », choisis « Télécharger le PDF A4 », pour télécharger un vrai fichier PDF. Les pages sont au format A4, avec 18 mm de marge de chaque côté, un en-tête et une pagination. Les paragraphes longs passent sur les pages suivantes. « Imprimer avec le navigateur » reste disponible si tu préfères. Le fichier .json reste nécessaire pour reprendre facilement l’édition.'],
  ['Mes données sont-elles envoyées au lycée ?','L’application ne transmet pas le contenu de ton projet au lycée, à Parcoursup ou à un service d’intelligence artificielle. Le travail est réalisé dans ton navigateur. Le site d’hébergement peut traiter les informations techniques nécessaires à son accès ; les sites externes appliquent leurs propres règles lorsque tu les ouvres.'],
  ['À quoi sert le brouillon sur mon appareil ?','C’est une copie de secours temporaire dans ce navigateur, uniquement si tu coches l’option. Elle n’est pas une sauvegarde durable : nettoyage du navigateur, navigation privée ou changement d’appareil peuvent la faire disparaître. Télécharge régulièrement ton fichier. Ne coche pas cette option sur un ordinateur partagé.'],
  ['Comment changer de projet ou effacer mes informations ?','Télécharge d’abord le carnet que tu veux garder. « Effacer ce carnet » supprime uniquement le projet ouvert et son brouillon local, après confirmation ; les fichiers déjà téléchargés restent sur ton appareil. Décocher l’option de brouillon supprime la copie locale mais laisse le carnet ouvert.'],
  ['Les formations ajoutées deviennent-elles des vœux ?','Non. Ce sont des pistes personnelles. Les candidatures, confirmations, réponses et inscriptions se font sur les plateformes et dans les établissements concernés. Les états du carnet sont déclaratifs : ils ne sont jamais synchronisés avec Parcoursup.'],
  ['Le choix des spécialités prédit-il mon admission ?','Non. Les liens proposés ici sont pédagogiques et ne sont pas un modèle statistique. La sélection d’un trio ou d’une paire ne garantit ni sa disponibilité au lycée ni une admission. Les attendus et conseils doivent être lus formation par formation.'],
  ['Pourquoi vois-je des données 2025 ?','L’explorateur utilise le jeu national Parcoursup 2025, hors apprentissage, actualisé le 9 mars 2026 et téléchargé le 8 septembre 2026. Il contient 14 252 enregistrements de formation. Il n’est pas l’offre actuelle et ne suit pas la procédure en direct.'],
  ['Que signifient les chiffres ?','Les places correspondent à la capacité de la formation. Les candidatures présentées sont celles de la phase principale. Les propositions et acceptations portent sur la campagne. Le taux d’accès est celui publié par le SIES : ce n’est ni une probabilité personnelle ni le rapport acceptations/candidatures. « Non publié » n’est pas zéro.'],
  ['Puis-je analyser les spécialités avec ces chiffres ?','Pas directement avec cet extrait open data : il ne contient ni doublettes de spécialités ni notes individuelles. L’outil de la fiche officielle Parcoursup présente des informations sur les profils, lorsqu’elles sont disponibles. Une association observée n’établit pas une causalité.'],
  ['Qui peut m’aider ?','Ton professeur principal, les professeurs des disciplines, le Psy-EN et le CIO peuvent accompagner ta réflexion. Le professeur documentaliste peut t’aider à trouver des sources. Pour un financement ou une difficulté sociale, demande un rendez-vous adapté sans déposer de détails sensibles dans le carnet.'],
  ['L’application fonctionne-t-elle sur téléphone et au clavier ?','L’interface s’adapte à la largeur de l’écran. Le bouton « Rubriques » ouvre le menu complet sur téléphone et les trois scénarios s’empilent pour rester lisibles. Utilise Tab pour parcourir les commandes, Entrée ou Espace pour agir et Échap pour fermer une fenêtre. Le téléchargement PDF A4 est indépendant du dialogue d’impression du navigateur. Le bouton « Rubriques » permet d’ouvrir le menu sur téléphone.'],
  ['Faut-il une connexion Internet ?','La première ouverture et le chargement du catalogue nécessitent Internet, comme les liens externes. L’application n’est pas prévue comme une application installable hors ligne. Télécharge ton projet avant de fermer ou de changer d’appareil.'],
  ['Les ressources et dates sont-elles mises à jour automatiquement ?','Non. Les contenus pédagogiques ont été vérifiés le 16 octobre 2026. Le catalogue conserve son millésime 2025. Les liens officiels peuvent évoluer et les guides datés restent ceux de leur année. Pour une candidature ou un choix réglementaire, utilise la fiche et le calendrier de ta session.']
  ].map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('')}</div>
  ${callout('Demander de l’aide, c’est aussi avancer.','Tu peux venir avec une envie, une hésitation ou simplement une question. Tu n’as pas besoin d’un projet achevé pour être accompagné.')}
  <div class="actions">${external(URLS.conseil,'Parler à un conseiller Onisep','btn primary')}${external(URLS.lycee,'Site du lycée','btn')}${btn('guide','Préparer mon entretien','',`data-id="entretien"`)}</div>
  ${section('Sources, périmètre et identité visuelle')}<div class="card"><h3>Des repères vérifiables</h3><p class="small">Catalogue : Parcoursup — traitement SIES, ministère chargé de l’enseignement supérieur. Réutilisation sous Licence Ouverte 2.0. Données agrégées par formation et établissement, sans données individuelles du lycée. Les textes de réflexion et les rapprochements par domaines sont des contenus pédagogiques, pas des conclusions statistiques.</p><div class="actions">${external(URLS.dataset,'Source des données','btn compact')}${external(URLS.data,'Visualisation officielle','btn compact')}${external(URLS.choix,'Conseils spécialités','btn compact')}${external(URLS.schema,'Schéma des études','btn compact')}</div><h3 style="margin-top:24px">Propriété et identité du site</h3><p class="small">Ce site est la propriété du Lycée Ambroise Paré, établissement public d’enseignement à Laval. L’identité reprend les logos fournis par le lycée, le bleu académique, le rouge patrimoine et le beige naturel. Les logos sont conservés sans déformation.</p><p class="small">L’outil est une aide à la réflexion. Les inscriptions, les candidatures et les décisions d’orientation suivent les procédures officielles et l’accompagnement de l’établissement. Pour signaler une erreur ou poser une question, adresse-toi à l’équipe du lycée.</p><img src="./assets/logo-horizontal.jpg" width="270" height="95" alt="Lycée Ambroise Paré · Laval" style="display:block;max-width:100%;height:auto;margin:22px 0"><h3>Sources pédagogiques vérifiées le ${UPDATED}</h3><ul class="compact-list">${VERIFIED_SOURCES.map(([label,url])=>`<li>${external(url,label)}</li>`).join('')}</ul></div>${foot()}`;}
function render(){const active=document.activeElement,action=active?.dataset?.action,id=active?.dataset?.id;renderNav();const handlers={accueil:renderHome,niveau:renderLevel,voies:renderPathways,specialites:renderSpecialties,domaines:renderDomains,formations:renderFormations,ressources:renderResources,projet:renderProject,aide:renderHelp};handlers[route]();if(action){const target=[...document.querySelectorAll('[data-action]')].find(n=>n.dataset.action===action&&n.dataset.id===id);target?.focus({preventScroll:true});}}
function routeChanged(initial=false){const next=location.hash.slice(1).split('?')[0];route=NAV.some(n=>n[0]===next)?next:'accueil';if(dialog.open)dialog.close();const mobile=$('.mobile-navigation');if(mobile)mobile.open=false;render();if(!initial){window.scrollTo({top:0,behavior:'instant'});$('#main').focus({preventScroll:true});}}

function download(content,filename,type){const blob=new Blob([content],{type});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500);}
function printContent(html){const root=$('#print-root');root.innerHTML=html;document.documentElement.classList.add('printing');if(dialog.open)dialog.close();const cleanup=()=>{document.documentElement.classList.remove('printing');window.removeEventListener('afterprint',cleanup);};window.addEventListener('afterprint',cleanup);requestAnimationFrame(()=>requestAnimationFrame(()=>window.print()));}
function exportProject(){const invalid=$('[data-budget]:invalid');if(invalid){invalid.reportValidity();toast('Corrige le montant de budget invalide avant de télécharger.');return;}saveDraft();const safe=cleanProject(project);download(JSON.stringify(safe,null,2),'Mon_projet_Ambroise_Pare_'+new Date().toISOString().slice(0,10)+'.json','application/json;charset=utf-8');dirty=false;toast('Fichier proposé au téléchargement. Conserve-le dans un emplacement privé pour reprendre ton projet.');}
function importProject(){const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.addEventListener('change',async()=>{const file=input.files?.[0];if(!file)return;if(file.size>2*1024*1024){toast('Ce fichier dépasse 2 Mo. Choisis un fichier projet exporté par Mon parcours.');return;}try{const candidate=cleanProject(JSON.parse(await file.text()));if(!confirm('Remplacer le carnet ouvert par ce fichier ? Télécharge d’abord le carnet actuel si tu souhaites le conserver.'))return;clearTimeout(saveTimer);project=candidate;comparePath=null;specMode=project.level==='terminale'?'pair':'trio';dirty=false;saveDraft();if(dialog.open)dialog.close();location.hash='projet';if(route==='projet')renderProject();toast('Projet repris. Tu peux continuer à le modifier.');}catch(err){toast('Import impossible : '+(err instanceof SyntaxError?'le fichier n’est pas un JSON valide.':err.message));}});input.click();}
function addChoice(r){if(project.choices.length>=40){toast('Le carnet contient déjà 40 pistes. Retire une piste avant d’en ajouter une.');return;}project.choices.push({id:'psup-'+r.id,title:r.title,school:r.school,city:r.city,url:safeURL(r.url),source:'Historique Parcoursup 2025 — à vérifier pour ma session',status:'À explorer',reason:'',question:'',motivation:''});changed();toast('Formation ajoutée à ton projet. Pense à télécharger ton fichier.');}
function toggleFormation(id){const r=findFormation(id);if(!r)return;const i=project.choices.findIndex(c=>c.id==='psup-'+id);if(i>=0){const c=project.choices[i];if((c.reason||c.question||c.motivation)&&!confirm('Retirer cette piste et les notes que tu as rédigées pour elle ?'))return;project.choices.splice(i,1);changed();toast('Piste retirée du carnet.');}else addChoice(r);if(route==='formations')renderFormationResults();if(dialog.open)openFormation(id);}
function manualChoice(){openDialog(`<p class="eyebrow">Une piste hors catalogue</p><h2 id="dialog-title">Ajouter ma propre possibilité.</h2><p class="notice">Tu peux ajouter une formation en apprentissage, hors Parcoursup ou un parcours à explorer.</p><form id="manual-choice-form"><label class="field">Formation ou projet *<input name="title" required maxlength="500" placeholder="Nom précis de la formation"></label><label class="field" style="margin-top:16px">Établissement<input name="school" maxlength="400"></label><label class="field" style="margin-top:16px">Ville<input name="city" maxlength="200"></label><label class="field" style="margin-top:16px">Lien officiel (facultatif, https)<input name="url" type="url" placeholder="https://…" maxlength="2000"></label><button class="btn primary" type="submit" style="margin-top:20px">Ajouter au projet</button><p class="notice" id="manual-error" role="alert"></p></form>`);}
document.addEventListener('submit',event=>{if(event.target.id!=='manual-choice-form')return;event.preventDefault();if(project.choices.length>=40){$('#manual-error').textContent='Maximum de 40 pistes atteint.';return;}const f=new FormData(event.target);const title=String(f.get('title')??'').trim();const url=String(f.get('url')??'').trim();if(!title|| (url&&!safeURL(url))){$('#manual-error').textContent='Ajoute un titre et, si besoin, un lien commençant par https://.';return;}project.choices.push({id:'manual-'+Date.now()+'-'+Math.random().toString(36).slice(2,6),title,school:String(f.get('school')??''),city:String(f.get('city')??''),url:safeURL(url),source:'Piste personnelle — informations à vérifier',status:'À explorer',reason:'',question:'',motivation:''});changed();dialog.close();if(route==='projet')renderProject('project-choices');else location.hash='projet';toast('Piste ajoutée au projet.');});
let filterTimer,resourceTimer;
document.addEventListener('input',event=>{const t=event.target;if(t.matches('[data-field]')){project[t.dataset.field]=t.value;changed();}if(t.matches('[data-establishments]')){project.establishments=t.value.split('\n').map(v=>v.trim()).filter(Boolean).slice(0,40);changed();}if(t.matches('[data-scenario]')){const s=project.scenarios[Number(t.dataset.scenario)];if(s){s[t.dataset.key]=t.value;changed();}}if(t.matches('[data-budget]')){if(t.value!==''&&(!Number.isFinite(Number(t.value))||Number(t.value)<0||Number(t.value)>100000)){t.setCustomValidity('Saisis un montant entre 0 et 100 000 €.');return;}t.setCustomValidity('');project.budget[t.dataset.budget]=t.value;changed();}if(t.matches('[data-choice]')){const c=project.choices[Number(t.dataset.choice)];if(c){c[t.dataset.key]=t.value;changed();}}if(t.matches('[data-task]')){const task=project.tasks[Number(t.dataset.task)];if(task){task[t.dataset.key]=t.type==='checkbox'?t.checked:t.value;changed();}}if(t.matches('[data-filter]')){formationFilters[t.dataset.filter]=t.type==='checkbox'?t.checked:t.value;page=1;clearTimeout(filterTimer);filterTimer=setTimeout(renderFormationResults,150);}if(t.matches('[data-resource-filter]')){resourceFilters[t.dataset.resourceFilter]=t.type==='checkbox'?t.checked:t.value;clearTimeout(resourceTimer);resourceTimer=setTimeout(renderResourceResults,120);}});
document.addEventListener('change',event=>{const t=event.target;if(t.matches('[data-stmg-specific]')){project.stmgSpecific=t.value;changed();if(route==='specialites')renderSpecialties();}if(t.matches('[data-current-path]')){project.currentPath=t.value;comparePath=null;changed();render();$('[data-current-path]')?.focus({preventScroll:true});}if(t.matches('[data-specialty-scope]')){specialtyScope=t.value;renderSpecialties();$('[data-specialty-scope]')?.focus({preventScroll:true});}if(t.dataset.check){project.checks[t.dataset.check]=t.checked;changed();}if(t.dataset.compare){if(t.checked&&!compare.includes(t.dataset.compare)){if(compare.length>=3){t.checked=false;toast('Trois formations maximum. Retire une sélection pour en choisir une autre.');return;}compare.push(t.dataset.compare);}else compare=compare.filter(id=>id!==t.dataset.compare);renderCompareBar();}if(t.id==='draft-consent'){if(t.checked){if(!confirm('Ce navigateur conservera un brouillon de secours lisible par les personnes utilisant le même profil. Est-ce bien ton appareil personnel ?')){t.checked=false;return;}draftEnabled=true;saveDraft();}else{try{localStorage.removeItem(STORAGE_KEY);draftEnabled=false;saveError='';toast('Brouillon local supprimé. Le carnet reste ouvert ; télécharge-le pour le conserver.');}catch{t.checked=true;saveError='La suppression du brouillon local a échoué. Utilise les paramètres du navigateur pour effacer les données de ce site.';}updateProjectIndicators();}}});
document.addEventListener('click',event=>{
  const scroll=event.target.closest('[data-scroll]');if(scroll){event.preventDefault();$('#'+scroll.dataset.scroll)?.scrollIntoView({behavior:'smooth'});return;}
  if(event.target.closest('[data-close-dialog]'))dialog.close();
  const el=event.target.closest('[data-action]');if(!el)return;const {action,id}=el.dataset;
  if(action==='compare-path'){comparePath=id;renderSpecialties();}
  if(action==='level'){project.level=id;comparePath=null;specMode=id==='terminale'?'pair':'trio';changed();render();$(`[data-action="level"][data-id="${id}"]`)?.focus({preventScroll:true});}
  if(action==='spec-mode'){specMode=id;renderSpecialties();}
  if(action==='specialty'){const old=project[specMode], next=toggleSelection(old,id,specMode==='trio'?3:2);if(old===next){toast(`Sélectionne au maximum ${specMode==='trio'?3:2} enseignements. Retire un choix pour en explorer un autre.`);return;}const issue=selectionIssue(next,project.options);if(issue){toast(issue);return;}project[specMode]=next;if(specMode==='trio')project.pair=project.pair.filter(v=>project.trio.includes(v));changed();renderSpecialties();$(`[data-action="specialty"][data-id="${id}"]`)?.focus({preventScroll:true});}
  if(action==='spec-clear'){project[specMode]=[];if(specMode==='trio')project.pair=[];changed();renderSpecialties();}
  if(action==='keep-pair'){project.pair=el.dataset.ids.split(',');specMode='pair';changed();renderSpecialties();toast('Hypothèse ajoutée au carnet. Tu peux la modifier ou l’enregistrer comme scénario.');}
  if(action==='compare-scenarios'){showScenarioCompare=!showScenarioCompare;renderSpecialties();}
  if(action==='domain-toggle'){project.domainIds=project.domainIds.includes(id)?project.domainIds.filter(x=>x!==id):[...project.domainIds,id];changed();render();}
  if(action==='pathway'){project.pathways=project.pathways.includes(id)?project.pathways.filter(x=>x!==id):[...project.pathways,id];changed();renderPathways();}
  if(action==='stmg-specific'){project.stmgSpecific=project.stmgSpecific===id?'':id;project.techSeries='stmg';changed();renderTrackCompare();}
  if(action==='save-track-scenario'){if(!project.stmgSpecific){toast('Choisis d’abord un enseignement spécifique à explorer.');return;}if(project.scenarios.length>=3){toast('Trois hypothèses sont déjà enregistrées. Retire-en une dans ton carnet.');return;}const title='STMG · '+STMG_SPECIFICS.find(v=>v.id===project.stmgSpecific).title;if(project.scenarios.some(v=>v.title===title)){toast('Cette hypothèse est déjà dans ton carnet.');return;}project.scenarios.push({id:'scenario-'+Date.now(),title,domainIds:[...project.domainIds],trio:[],pair:[],pathway:'technologique',techSeries:'stmg',stmgSpecific:project.stmgSpecific,notes:''});changed();toast('Hypothèse STMG enregistrée dans ton carnet.');}
  if(action==='tech-detail')openTech(id);
  if(action==='tech-save'){project.techSeries=project.techSeries===id?'':id;if(project.techSeries&&!project.pathways.includes('technologique'))project.pathways.push('technologique');changed();if(dialog.open)openTech(id);else renderPathways();toast(project.techSeries?'Série ajoutée à Mon projet.':'Série retirée de Mon projet.');}
  if(action==='reorientation-save'){if(project.reorientation&&!project.pathways.includes('professionnelle'))project.pathways.push('professionnelle');changed();toast('Réflexion conservée dans Mon projet.');}
  if(action==='local-option'){if(id==='bachibac'&&!project.options.includes(id)&&project.trio.concat(project.pair).includes('llcer-espagnol')){toast('Bachibac espagnol et spécialité LLCER espagnol ne peuvent pas être cumulés. Vérifie ton projet avec l’équipe.');return;}project.options=project.options.includes(id)?project.options.filter(x=>x!==id):[...project.options,id];changed();renderSpecialties();}
  if(action==='save-scenario'){const pair=el.dataset.ids.split(',');if(project.scenarios.some(s=>s.pair.length===pair.length&&pair.every(id=>s.pair.includes(id))&&s.trio?.length===project.trio.length&&project.trio.every(id=>s.trio.includes(id)))){toast('Ce scénario est déjà enregistré dans ton carnet.');return;}if(project.scenarios.length>=3){toast('Trois scénarios sont déjà enregistrés. Retire-en un dans Mon projet pour en garder un autre.');return;}const n=project.scenarios.length;project.scenarios.push({id:'scenario-'+Date.now(),title:`Scénario ${String.fromCharCode(65+n)}`,domainIds:[...project.domainIds],trio:[...project.trio],pair,techSeries:'',pathway:'generale',notes:''});project.pair=pair;changed();toast(`Scénario ${String.fromCharCode(65+n)} enregistré.`);}
  if(action==='domain')openDomain(id);
  if(action==='guide')openGuide(id);
  if(action==='domain-search'){const d=DOMAINS.find(x=>x.id===id);formationFilters={q:d.search,academy:'',family:'',status:'',savedOnly:false};page=1;if(dialog.open)dialog.close();location.hash='formations';if(route==='formations')renderFormations();}
  if(action==='family-search'){formationFilters={q:'',academy:'',family:id,status:'',savedOnly:false};page=1;dialog.close();location.hash='formations';if(route==='formations')renderFormations();}
  if(action==='add-domain-action'){const d=DOMAINS.find(x=>x.id===id);if(project.tasks.length>=100){toast('Maximum de 100 démarches atteint.');return;}project.tasks.push({id:'task-'+Date.now(),text:d.action,date:'',done:false});changed();toast('Action ajoutée dans Mon projet.');}
  if(action==='resource-save'){project.resources=project.resources.includes(id)?project.resources.filter(x=>x!==id):[...project.resources,id];changed();el.innerHTML=project.resources.includes(id)?'✓ Repérée':'+ Repérer';el.setAttribute('aria-pressed',String(project.resources.includes(id)));if(route==='ressources')renderResourceResults();}
  if(action==='resource-reset'){resourceFilters={q:'',category:'',level:'',savedOnly:false};renderResources();}
  if(action==='reset-filters'){formationFilters={q:'',academy:'',family:'',status:'',savedOnly:false};page=1;renderFormations();}
  if(action==='retry-data')renderFormations();
  if(action==='page-prev'||action==='page-next'){page+=action==='page-prev'?-1:1;renderFormationResults();$('#formation-results')?.scrollIntoView({behavior:'smooth'});}
  if(action==='formation')openFormation(id);
  if(action==='save-formation')toggleFormation(id);
  if(action==='print-formation'){const r=findFormation(id);if(r)void downloadPDF(formationHTML(r),'Fiche_formation_Ambroise_Pare.pdf');}
  if(action==='compare-open')openCompare();
  if(action==='compare-clear'){compare=[];renderFormationResults();}
  if(action==='project-preview')openDialog(`<h2 id="dialog-title" class="sr-only">Aperçu de mon projet</h2><div class="actions" style="margin-bottom:20px">${btn('project-print','Télécharger le PDF A4','primary')}${btn('project-export','Télécharger le fichier modifiable')}</div>${projectHTML(project,SPECIALTIES,RESOURCES,DOMAINS,DOMAIN_RULES,LOCAL_OFFERS)}`);
  if(action==='project-print')void downloadPDF(projectHTML(project,SPECIALTIES,RESOURCES,DOMAINS,DOMAIN_RULES,LOCAL_OFFERS),'Mon_projet_Ambroise_Pare.pdf');
  if(action==='project-browser-print')printContent(projectHTML(project,SPECIALTIES,RESOURCES,DOMAINS,DOMAIN_RULES,LOCAL_OFFERS));
  if(action==='print-guide'){const g=GUIDES.find(x=>x.id===id);if(g)void downloadPDF(guideHTML(g,RESOURCES,UPDATED),'Fiche_pratique_Ambroise_Pare.pdf');}
  if(action==='project-export')exportProject();
  if(action==='import')importProject();
  if(action==='manual-choice')manualChoice();
  if(action==='remove-choice'){if(confirm('Retirer cette piste et les notes associées du carnet ?')){project.choices.splice(Number(el.dataset.index),1);changed();renderProject('project-choices');}}
  if(action==='add-task'){if(project.tasks.length>=100){toast('Maximum de 100 démarches atteint.');return;}project.tasks.push({id:'task-'+Date.now(),text:'',date:'',done:false});changed();renderProject('project-actions');$(`[data-task="${project.tasks.length-1}"][data-key="text"]`)?.focus({preventScroll:true});}
  if(action==='remove-task'){const i=Number(el.dataset.index);if(project.tasks[i].text&&!confirm('Retirer cette démarche ?'))return;project.tasks.splice(i,1);changed();renderProject('project-actions');}
  if(action==='seed-tasks'){const proposed=['Consulter une formation officielle','Comparer deux établissements','Vérifier une option ou un dispositif','Parler au professeur principal','Rencontrer le Psy-EN','Participer à une journée portes ouvertes','Consulter la carte Parcoursup','Réexaminer le scénario choisi'];for(const text of proposed)if(!project.tasks.some(t=>t.text===text)&&project.tasks.length<100)project.tasks.push({id:'task-'+Date.now()+'-'+project.tasks.length,text,date:'',done:false});changed();renderProject('project-actions');}
  if(action==='remove-scenario'){project.scenarios.splice(Number(el.dataset.index),1);changed();renderProject('project-specialties');}
  if(action==='load-scenario'){const s=project.scenarios[Number(el.dataset.index)];if(!s)return;project.domainIds=[...s.domainIds];project.trio=[...(s.trio||[])];project.pair=[...s.pair];project.techSeries=s.techSeries;project.stmgSpecific=s.stmgSpecific||'';comparePath=s.techSeries==='stmg'?'stmg':s.pathway==='generale'?'generale':null;project.currentPath=s.techSeries==='stmg'?'stmg':s.pathway==='technologique'?'technologique':'generale';specMode=project.trio.length===3?'trio':'pair';changed();location.hash='specialites';if(route==='specialites')renderSpecialties();toast('Hypothèse reprise. Tu peux la faire évoluer.');}
  if(action==='clear-project'){if(!confirm('Effacer ce carnet et son brouillon local ? Cette action n’efface pas les fichiers déjà téléchargés. Télécharge ton projet avant de continuer si tu veux le conserver.'))return;try{localStorage.removeItem(STORAGE_KEY);}catch{toast('La copie locale n’a pas pu être supprimée. Efface les données de ce site dans les réglages du navigateur.');return;}clearTimeout(saveTimer);project=newProject();comparePath=null;dirty=false;draftEnabled=false;saveError='';renderProject();toast('Carnet ouvert et brouillon local effacés. Tes fichiers téléchargés sont conservés.');}
});
$('.dialog-close').addEventListener('click',()=>dialog.close());
dialog.addEventListener('click',event=>{if(event.target===dialog){const b=dialog.getBoundingClientRect();if(event.clientX<b.left||event.clientX>b.right||event.clientY<b.top||event.clientY>b.bottom)dialog.close();}});
window.addEventListener('hashchange',()=>routeChanged());
window.addEventListener('beforeunload',event=>{if(dirty&&(!draftEnabled||saveError)){event.preventDefault();event.returnValue='';}});
window.addEventListener('pagehide',()=>saveDraft());
window.addEventListener('storage',event=>{if(event.key===STORAGE_KEY&&draftEnabled){saveError='Le brouillon a changé dans un autre onglet. Ton texte reste ici : télécharge-le avant de poursuivre. La copie automatique est suspendue.';draftEnabled=false;clearTimeout(saveTimer);updateProjectIndicators();}});
specMode=project.level==='terminale'?'pair':'trio';
routeChanged(true);if(saveError)toast(saveError);
